  if (nm < 490) return "#0040ff";
  if (nm < 510) return "#00c8a0";
  if (nm < 580) return "#67e8b0";
  if (nm < 645) return "#ffae00";
  if (nm < 750) return "#ff2b2b";
  return "#8a0000";
}
